<?php $canEdit = (can('compliance.manage') || can('compliance.update')) && $o['archived_at'] === null; $late = in_array($o['status'], ['not_started', 'in_progress', 'non_compliant'], true) && $o['due_date'] < date('Y-m-d'); ?>
<div class="page-head"><div><h1><?= e($o['code']) ?> — <?= e($o['title']) ?></h1><p class="sub"><?= status_badge($o['status']) ?><?= $late ? ' <span class="badge danger">' . e(t('risk.overdue')) . '</span>' : '' ?><?= $o['archived_at'] ? ' <span class="badge warn">' . e(t('risk.archived')) . '</span>' : '' ?></p></div>
<div class="actions"><a class="btn secondary" href="<?= e(url('compliance')) ?>"><?= e(t('common.back')) ?></a>
<?php if (can('compliance.manage')): ?><a class="btn" href="<?= e(url('compliance/' . $o['id'] . '/edit')) ?>"><?= e(t('common.edit')) ?></a>
<?php if ($o['frequency'] !== 'once' && !$o['archived_at']): ?><form method="post" class="inline" action="<?= e(url('compliance/' . $o['id'] . '/roll')) ?>" data-confirm="<?= e(t('comp.confirm_roll')) ?>"><?= csrf_field() ?><button class="btn secondary" type="submit"><?= e(t('comp.roll')) ?></button></form><?php endif; ?>
<form method="post" class="inline" action="<?= e(url('compliance/' . $o['id'] . '/archive')) ?>" data-confirm="<?= e(t($o['archived_at'] ? 'risk.confirm_restore' : 'risk.confirm_archive')) ?>"><?= csrf_field() ?><button class="btn danger" type="submit"><?= e(t($o['archived_at'] ? 'common.restore' : 'common.archive')) ?></button></form><?php endif; ?></div></div>
<div class="grid cols-2"><section class="card"><h2><?= e(t('comp.details')) ?></h2><dl class="details">
<dt><?= e(t('comp.source')) ?></dt><dd><?= e($o['source']) ?></dd><dt><?= e(t('comp.department')) ?></dt><dd><?= e(lname($o, 'dept')) ?></dd><dt><?= e(t('comp.owner')) ?></dt><dd><?= e($o['owner_name']) ?></dd>
<dt><?= e(t('comp.frequency')) ?></dt><dd><?= e(t('enum.freq.' . $o['frequency'])) ?></dd><dt><?= e(t('comp.due_date')) ?></dt><dd><?= e($o['due_date']) ?></dd><dt><?= e(t('comp.last_reviewed')) ?></dt><dd><?= e(fdate($o['last_reviewed_on']) ?: '—') ?></dd>
<dt><?= e(t('comp.description')) ?></dt><dd class="pre"><?= e($o['description'] ?? '—') ?></dd><dt><?= e(t('comp.status_note')) ?></dt><dd class="pre"><?= e($o['status_note'] ?? '—') ?></dd></dl></section>
<?php if ($canEdit): ?><section class="card" id="status"><h2><?= e(t('comp.update_status')) ?></h2>
<form method="post" action="<?= e(url('compliance/' . $o['id'] . '/status')) ?>" novalidate><?= csrf_field() ?>
<?= ff('select', 'status', 'comp.status', $o['status'], ['blank' => false, 'options' => opts(['not_started', 'in_progress', 'compliant', 'non_compliant', 'not_applicable'], fn($x) => t('enum.obl_status.' . $x), null) ?: []]) ?>
<?= ff('textarea', 'status_note', 'comp.status_note', $o['status_note'] ?? '', ['hint' => t('comp.status_note_hint')]) ?>
<button class="btn" type="submit"><?= e(t('common.update')) ?></button></form></section><?php endif; ?></div>
<section class="card" id="attachments"><h2><?= e(t('comp.evidence')) ?></h2>
<?php if (!$attachments): ?><p class="muted"><?= e(t('upload.empty')) ?></p><?php else: ?><ul><?php foreach ($attachments as $a): ?><li><a href="<?= e(url('attachments/' . $a['id'])) ?>"><?= e($a['original_name']) ?></a> <span class="muted">(<?= e(round($a['size_bytes'] / 1024)) ?> KB · <?= e($a['full_name']) ?> · <?= e(fdate($a['created_at'])) ?>)</span>
<?php if ($canEdit): ?><form method="post" class="inline" action="<?= e(url('attachments/' . $a['id'] . '/delete')) ?>" data-confirm="<?= e(t('upload.confirm_delete')) ?>"><?= csrf_field() ?><button class="btn small danger" type="submit"><?= e(t('common.delete')) ?></button></form><?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php if ($canEdit): ?><form method="post" enctype="multipart/form-data" action="<?= e(url('compliance/' . $o['id'] . '/attachments')) ?>"><?= csrf_field() ?><div class="field"><label for="file"><?= e(t('upload.choose')) ?></label><input type="file" id="file" name="file" required accept=".pdf,.png,.jpg,.jpeg,.txt,.docx,.xlsx"><p class="hint"><?= e(t('upload.rules', ['max' => '5 MB', 'types' => 'pdf, png, jpg, txt, docx, xlsx'])) ?></p></div><button class="btn secondary" type="submit"><?= e(t('upload.submit')) ?></button></form><?php endif; ?></section>
